sp_widget.css:
/* Styling for the request table */
.table {
    width: 100%;
    border-collapse: collapse;
}

.table th, .table td {
    text-align: left;
    padding: 12px;
    border: 1px solid #ddd;
}

.table th {
    background-color: #0077cc;
    color: white;
    font-weight: bold;
}

.table tr:nth-child(even) {
    background-color: #f2f2f2;
}

.table tr:hover {
    background-color: #ddd;
}

/* Button styling */
.btn {
    padding: 6px 12px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-primary {
    background-color: #0077cc;
    color: white;
}

.btn-primary:hover {
    background-color: #005fa3;
}

sp_widget.script:
(function() {
    var result = [];
    var tables = ['x_1583423_hr_hroo_employee_onboarding', 'x_1583423_hr_hroo_employee_offboarding']; // Replace with actual table names

    tables.forEach(function(table) {
        var gr = new GlideRecord(table);
        gr.orderByDesc('sys_created_on');
        gr.query();
        while (gr.next()) {
            result.push({
                sys_id: gr.getValue('sys_id'),
                number: gr.getValue('number'),
                type: table.includes('onboarding') ? 'Onboarding' : 'Offboarding',
                status: gr.getDisplayValue('state'),
                employee: gr.getDisplayValue('employee_name'),
                created_on: gr.getDisplayValue('sys_created_on')
            });
        }
    });

    data.requests = result;
})();
